H,W,N=map(int,sys.stdin.readline().split())
grid=[["."]*W for i in range(H)]
directions=((-1,0),(0,1),(1,0),(0,-1))
dirNum=0
x=0
y=0
for i in range(N):
    if grid[y][x]==".":
        grid[y][x]="#"
        dirNum+=1
    else:
        grid[y][x]="."
        dirNum-=1
    new_x = x + directions[dirNum%4][1]
    new_y = y + directions[dirNum%4][0]

    if new_x >= W:
        new_x -= W
    elif new_x < 0:
        new_x += W

    if new_y >= H:
        new_y -= H
    elif new_y < 0:
        new_y += H

    y = new_y
    x = new_x

for clm in grid:
    print(*clm)

