def solve(mid):
    visited = [-1 for i in range(n + 1)]

    for start in range(1, n + 1):
        if visited[start] != -1:
            continue

        visited[start] = 0
        que = [start]
        while que:
            next_que = []
            while que:
                v = que.pop()
                for nv, c in graph[v]:
                    if c >= mid:
                        break
                    if visited[nv] == visited[v]:
                        return False
                    if visited[nv] == -1:
                        visited[nv] = visited[v] ^ 1
                        next_que.append(nv)
            que = next_que

    return True

