    for i in range(1, n+1):
        if visited[i] != -1:
            continue

        visited[i] = 0
        que = [i]
        while que:
            nque = []
            while que:
                v = que.pop()
                for nv, c in graph[v]:
                    if c >= w:
                        break
                    if visited[nv] == visited[v]:
                        return False
                    if visited[nv] == -1:
                        visited[nv] = visited[v] ^ 1
                        nque.append(nv)
                    else:
                        continue
            que = nque

    return True


