    if a[i] < b:
        dp1[i + a[i]][a[i]] += dp2[i]
        dp1[i + a[i]][a[i]] %= mod
    else:
        for j in range(1, (n - i - 1) // a[i] + 1):
            dp2[i + j * a[i]] += dp2[i]
            dp2[i + j * a[i]] %= mod

