can_l = set()
piano = "wbwbwwbwbwbwwbwbwwbwbwbwwbwbwwbwbwbwwbwbwwbwbwbwwbwbwwbwbwbwwbwbwwbwbwbw"
for i in range(len(piano) - 1): # How many characters to take
    for j in range(i + 1, len(piano)): # From which character to start taking
        A = [W, B]
        for k in range(j, i, -1): # Which character amongst the taken ones to exclude
            if piano[k] == "w":
                A[0] -= 1
            if piano[k] == "b":
                A[1] -= 1
            if A[0] < 0 or A[1] < 0:
                break
        else:
            can_l.add(tuple(A))

